/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { once } from 'node:events';
const directory = await mkdtemp(join(process.cwd(), '.launch-check-'));
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'db.sqlite') }, detached: true });
try {
  const port = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('Launch timed out')), 5000);
    child.stdout.on('data', chunk => {
      const match = /listening on port (\\d+)/.exec(String(chunk));
      if (match) { clearTimeout(timeout); resolve(match[1]); }
    });
    child.once('error', reject);
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  if (response.status !== 200 || JSON.stringify(await response.json()) !== '"'{\"status\":\"ok\"}') throw new Error('Health failed');
  console.log('npm start launch and health check passed');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
JS
